const V3_REVIEW_CARDS=[{"id":"rule-1","lesson":"senales","front":"¿Qué debes hacer si una señal de agente contradice un semáforo?","es":"Obedecer la indicación del agente.","ru":"Сигналы регулировщика имеют высший приоритет.","ruleId":"v3-1","source":"rules"},{"id":"rule-2","lesson":"senales","front":"¿Qué prevalece entre una señal provisional de obras y una señal vertical fija?","es":"La señal circunstancial o provisional aplicable.","ru":"Временная дорожная сигнализация имеет приоритет над постоянной.","ruleId":"v3-2","source":"rules"},{"id":"rule-3","lesson":"senales","front":"Una señal octogonal roja con STOP exige…","es":"Detener el vehículo por completo y ceder el paso.","ru":"STOP требует полной остановки даже на пустой дороге.","ruleId":"v3-3","source":"signs"},{"id":"rule-4","lesson":"senales","front":"¿Qué representa un triángulo blanco invertido con borde rojo?","es":"Ceder el paso a quienes tienen preferencia.","ru":"Перевёрнутый треугольник — «уступи дорогу».","ruleId":"v3-4","source":"signs"},{"id":"rule-5","lesson":"senales","front":"¿Qué expresa normalmente un círculo azul con flecha blanca?","es":"Dirección obligatoria indicada por la flecha.","ru":"Синий круг со стрелкой задаёт обязательное направление.","ruleId":"v3-5","source":"signs"},{"id":"rule-6","lesson":"senales","front":"Una señal redonda con borde rojo y un número suele indicar…","es":"Velocidad máxima indicada en km/h.","ru":"Красная окружность с числом обозначает максимальную скорость.","ruleId":"v3-6","source":"signs"},{"id":"rule-7","lesson":"senales","front":"¿Qué significado general tiene un triángulo con borde rojo y fondo blanco?","es":"Advierte de un peligro próximo.","ru":"Треугольник предупреждает об опасности, требуя повышенного внимания.","ruleId":"v3-7","source":"signs"},{"id":"rule-8","lesson":"senales","front":"Cuando un semáforo está rojo pero hay una flecha verde iluminada, debes…","es":"Seguir solo la dirección de la flecha y ceder cuando corresponda.","ru":"Зелёная дополнительная стрелка разрешает соответствующее направление с соблюдением приоритета.","ruleId":"v3-8","source":"rules"},{"id":"rule-9","lesson":"senales","front":"¿Qué indica una línea continua longitudinal ordinaria?","es":"No, salvo las excepciones reglamentarias.","ru":"Сплошную линию пересекать обычно запрещено, кроме предусмотренных исключений.","ruleId":"v3-9","source":"rules"},{"id":"rule-10","lesson":"senales","front":"Ante una señal de prohibido entrar, ¿puedes acceder si la vía parece vacía?","es":"No entrar en el sentido prohibido.","ru":"Знак «въезд запрещён» действует и на пустой дороге.","ruleId":"v3-10","source":"signs"},{"id":"rule-11","lesson":"senales","front":"Una señal cuadrada azul con una P blanca anuncia…","es":"Un lugar o zona de estacionamiento señalizado.","ru":"Синяя P указывает место или зону парковки.","ruleId":"v3-11","source":"signs"},{"id":"rule-12","lesson":"senales","front":"¿Qué prevalece, como regla general, entre una señal vertical y una marca vial contradictoria?","es":"La señal vertical prevalece sobre las marcas viales.","ru":"В установленной иерархии вертикальный знак выше разметки.","ruleId":"v3-12","source":"rules"},{"id":"rule-13","lesson":"senales","front":"¿Qué caracteriza una señal de limitación de velocidad temporal en obras?","es":"La limitación temporal mientras sea aplicable.","ru":"Временные ограничения во время дорожных работ обязательны.","ruleId":"v3-13","source":"rules"},{"id":"rule-14","lesson":"senales","front":"¿Puede una marca amarilla de obras prevalecer sobre una línea blanca que conduce a otro carril?","es":"El trazado provisional indicado por las obras.","ru":"При временной организации движения следуют актуальной разметке и знакам.","ruleId":"v3-14","source":"rules"},{"id":"rule-15","lesson":"senales","front":"¿Qué debe hacerse ante una señal de peligro por ciclistas?","es":"Extremar la atención y adaptar velocidad y separación.","ru":"Предупреждение о велосипедистах требует осторожности.","ruleId":"v3-15","source":"signs"},{"id":"rule-16","lesson":"prioridad","front":"En una intersección sin regulación, ¿a quién cedes normalmente?","es":"Ceder a los vehículos que llegan por la derecha.","ru":"Без знаков обычно уступают тому, кто справа, с исключениями.","ruleId":"v3-16","source":"rules"},{"id":"rule-17","lesson":"prioridad","front":"Al entrar en una glorieta señalizada, ¿quién tiene prioridad?","es":"Los vehículos que ya circulan por la glorieta.","ru":"На круге приоритет у уже движущихся по нему машин.","ruleId":"v3-17","source":"rules"},{"id":"rule-18","lesson":"prioridad","front":"Quieres girar a la izquierda y viene un vehículo de frente: ¿qué haces?","es":"Ceder a los vehículos de frente con preferencia.","ru":"При левом повороте уступай встречному транспорту, если у него преимущество.","ruleId":"v3-18","source":"rules"},{"id":"rule-19","lesson":"prioridad","front":"Al salir de una propiedad privada a la vía pública, debes…","es":"A los usuarios de la vía y de la acera que corresponda.","ru":"При выезде из гаража уступают пользователям дороги и тротуара.","ruleId":"v3-19","source":"rules"},{"id":"rule-20","lesson":"prioridad","front":"¿Qué haces si un peatón está cruzando un paso señalizado?","es":"Cederle el paso y detenerte si es necesario.","ru":"На пешеходном переходе уступай и при необходимости остановись.","ruleId":"v3-20","source":"rules"},{"id":"rule-21","lesson":"prioridad","front":"En una intersección sin señales, un tranvía se acerca: ¿qué debes considerar?","es":"El tranvía tiene prioridad en los supuestos reglamentarios.","ru":"У трамвая есть установленный приоритет в нерегулируемых пересечениях.","ruleId":"v3-21","source":"rules"},{"id":"rule-22","lesson":"prioridad","front":"¿Qué haces si un vehículo prioritario en servicio urgente se aproxima señalizando?","es":"Facilitarle el paso sin crear peligro.","ru":"Нужно безопасно пропустить экстренную службу.","ruleId":"v3-22","source":"rules"},{"id":"rule-23","lesson":"prioridad","front":"En un estrechamiento señalizado, ¿qué debes observar primero?","es":"La señal de prioridad del estrechamiento.","ru":"На узком участке в первую очередь руководствуются знаками.","ruleId":"v3-23","source":"rules"},{"id":"rule-24","lesson":"prioridad","front":"¿Qué conducta es correcta si otro coche no respeta tu prioridad?","es":"Reducir la velocidad y evitar el conflicto.","ru":"Приоритет не отменяет обязанность предотвращать столкновение.","ruleId":"v3-24","source":"rules"},{"id":"rule-25","lesson":"prioridad","front":"Al incorporarte a una carretera desde el arcén, ¿qué debes hacer?","es":"Ceder a quienes circulan y realizar la maniobra con seguridad.","ru":"Выезжая с обочины, уступи транспортному потоку.","ruleId":"v3-25","source":"rules"},{"id":"rule-26","lesson":"prioridad","front":"¿Qué prevalece cuando un agente regula manualmente una rotonda?","es":"La instrucción del agente.","ru":"Регулировщик может изменить обычный порядок движения.","ruleId":"v3-26","source":"rules"},{"id":"rule-27","lesson":"prioridad","front":"¿Debes entrar en un cruce si vas a quedar bloqueándolo?","es":"Esperar antes de invadirlo aunque tengas verde.","ru":"Не въезжай на перекрёсток, если заблокируешь его.","ruleId":"v3-27","source":"rules"},{"id":"rule-28","lesson":"prioridad","front":"Si circulas por una vía pavimentada y otro vehículo sale de una vía sin pavimentar, ¿qué suele ocurrir?","es":"Tiene prioridad el que circula por la vía pavimentada.","ru":"При отсутствии знаков дорога с покрытием имеет преимущество перед грунтовой.","ruleId":"v3-28","source":"rules"},{"id":"rule-29","lesson":"prioridad","front":"¿Qué haces ante un paso de ciclistas señalizado con usuarios cruzándolo?","es":"Adaptar la maniobra y respetar su prioridad aplicable.","ru":"Следует соблюдать правила приоритета велосипедистов на обозначенном переходе.","ruleId":"v3-29","source":"rules"},{"id":"rule-30","lesson":"prioridad","front":"¿Una luz verde garantiza que la intersección está libre de conflictos?","es":"Avanzar solo cuando sea seguro y respetando sus derechos.","ru":"Зелёный свет не позволяет подвергать опасности людей на переходе.","ruleId":"v3-30","source":"rules"},{"id":"rule-31","lesson":"velocidad","front":"¿Cuál es el límite genérico para turismos en autopista fuera de poblado?","es":"120 km/h.","ru":"Для легкового автомобиля на автомагистрали вне города обычно 120 км/ч.","ruleId":"v3-31","source":"speeds"},{"id":"rule-32","lesson":"velocidad","front":"¿Cuál es el límite genérico para turismos en carretera convencional fuera de poblado?","es":"90 km/h.","ru":"Обычно 90 км/ч на обычной загородной дороге.","ruleId":"v3-32","source":"speeds"},{"id":"rule-33","lesson":"velocidad","front":"¿Cuál es el límite genérico de una calle urbana de un solo carril por sentido?","es":"30 km/h.","ru":"На городской улице с одной полосой в каждом направлении обычно 30 км/ч.","ruleId":"v3-33","source":"speeds"},{"id":"rule-34","lesson":"velocidad","front":"¿Cuál es el límite genérico en plataforma única de calzada y acera?","es":"20 km/h.","ru":"Общее ограничение на улице с единой платформой тротуара и дороги — 20 км/ч.","ruleId":"v3-34","source":"speeds"},{"id":"rule-35","lesson":"velocidad","front":"¿Cuál es el límite genérico urbano con al menos dos carriles por sentido?","es":"50 km/h.","ru":"На городской дороге с двумя и более полосами в направлении обычно 50 км/ч.","ruleId":"v3-35","source":"speeds"},{"id":"rule-36","lesson":"velocidad","front":"Al aumentar la velocidad, la distancia de frenado generalmente…","es":"Aumenta de forma muy notable, aproximadamente con el cuadrado de la velocidad.","ru":"Тормозной путь сильно растёт с повышением скорости, примерно пропорционально квадрату.","ruleId":"v3-36","source":"rules"},{"id":"rule-37","lesson":"velocidad","front":"Ante lluvia intensa, ¿cómo debes ajustar velocidad y distancia?","es":"Reducir velocidad y aumentar la distancia de seguridad.","ru":"При дожде снижай скорость и увеличивай дистанцию.","ruleId":"v3-37","source":"rules"},{"id":"rule-38","lesson":"velocidad","front":"Si el límite es 90 km/h, ¿puedes sobrepasarlo al adelantar en una carretera convencional?","es":"No, el límite máximo sigue vigente.","ru":"Превышать максимум для обгона больше нельзя.","ruleId":"v3-38","source":"speeds"},{"id":"rule-39","lesson":"velocidad","front":"¿Qué determina la velocidad segura además del límite máximo?","es":"Una velocidad adaptada a visibilidad y circunstancias, posiblemente menor.","ru":"Максимум — не обязательная скорость: учитывай видимость и условия.","ruleId":"v3-39","source":"rules"},{"id":"rule-40","lesson":"velocidad","front":"¿Qué efecto tiene el tiempo de reacción sobre la distancia total de detención?","es":"Aumenta.","ru":"Промедление реакции увеличивает путь до полной остановки.","ruleId":"v3-40","source":"rules"},{"id":"rule-41","lesson":"velocidad","front":"Al acercarte a una zona escolar señalizada, debes…","es":"Una velocidad especialmente prudente y ajustada al riesgo.","ru":"Рядом со школой скорость нужно снизить по обстоятельствам.","ruleId":"v3-41","source":"rules"},{"id":"rule-42","lesson":"velocidad","front":"¿Puede una señal específica establecer un máximo inferior al límite genérico?","es":"El máximo de 30 km/h de la señal.","ru":"Специальный знак ограничения имеет силу.","ruleId":"v3-42","source":"rules"},{"id":"rule-43","lesson":"velocidad","front":"Ante una curva con visibilidad limitada, ¿qué debes hacer antes de entrar?","es":"La velocidad previamente para poder mantener control.","ru":"Скорость перед поворотом выбирают заранее с учётом сцепления и видимости.","ruleId":"v3-43","source":"rules"},{"id":"rule-44","lesson":"velocidad","front":"¿Qué diferencia hay entre límite de velocidad y velocidad adecuada?","es":"No; puede ser necesario circular mucho más despacio.","ru":"Юридический максимум не гарантирует безопасную скорость.","ruleId":"v3-44","source":"rules"},{"id":"rule-45","lesson":"velocidad","front":"La distancia de reacción depende principalmente de…","es":"La velocidad y el tiempo de reacción.","ru":"Дистанция реакции зависит от скорости и задержки реакции.","ruleId":"v3-45","source":"rules"},{"id":"rule-46","lesson":"maniobras","front":"Antes de cambiar de carril, ¿qué secuencia general es segura?","es":"Observación, señalización y ejecución si es seguro.","ru":"Перед манёвром посмотри, обозначь намерение и действуй безопасно.","ruleId":"v3-46","source":"rules"},{"id":"rule-47","lesson":"maniobras","front":"¿Qué debes comprobar especialmente al cambiar de carril junto a una moto?","es":"Espejos y ángulo muerto.","ru":"Мотоцикл может находиться в слепой зоне.","ruleId":"v3-47","source":"rules"},{"id":"rule-48","lesson":"maniobras","front":"¿Se permite dar marcha atrás por haber pasado una salida de autopista?","es":"No; sigue hasta una salida permitida.","ru":"На скоростных дорогах сдавать назад к пропущенному съезду запрещено.","ruleId":"v3-48","source":"rules"},{"id":"rule-49","lesson":"maniobras","front":"¿Para qué se usa el intermitente antes de una maniobra?","es":"Tu intención; no concede prioridad.","ru":"Поворотник предупреждает, но не даёт преимущества.","ruleId":"v3-49","source":"rules"},{"id":"rule-50","lesson":"maniobras","front":"Al adelantar a una bicicleta donde hay dos carriles por sentido, la regla de 2026 exige…","es":"Cambiar por completo de carril y dejar separación segura.","ru":"С 2026 года при двух и более полосах в направлении для обгона велосипедиста нужно полностью сменить полосу.","ruleId":"v3-50","source":"vulnerables2026"},{"id":"rule-51","lesson":"maniobras","front":"En una calzada de un carril por sentido, ¿qué distancia lateral general mínima dejas al adelantar a un ciclista?","es":"Al menos 1,5 m cuando se realice el adelantamiento.","ru":"Для обгона велосипедиста нужна боковая дистанция не менее 1,5 м.","ruleId":"v3-51","source":"vulnerables2026"},{"id":"rule-52","lesson":"maniobras","front":"¿Qué precaución debe preceder a la apertura de la puerta tras estacionar?","es":"Si se aproximan ciclistas, motos u otros usuarios.","ru":"Прежде чем открыть дверь, проверь приближающийся транспорт.","ruleId":"v3-52","source":"rules"},{"id":"rule-53","lesson":"maniobras","front":"Al salir de un aparcamiento en línea, ¿qué debes hacer?","es":"Señalizar y ceder a quienes circulan.","ru":"При выезде с парковки уступи потоку.","ruleId":"v3-53","source":"rules"},{"id":"rule-54","lesson":"maniobras","front":"¿Puedes usar el arcén como carril de adelantamiento ordinario?","es":"No, salvo supuestos expresamente permitidos.","ru":"Обочина не служит обычной полосой обгона.","ruleId":"v3-54","source":"rules"},{"id":"rule-55","lesson":"maniobras","front":"¿Qué haces si no puedes realizar un giro con seguridad?","es":"Continuar y buscar otra ruta segura.","ru":"Не совершай опасный манёвр ради маршрута навигатора.","ruleId":"v3-55","source":"rules"},{"id":"rule-56","lesson":"maniobras","front":"¿Cuándo puedes iniciar un adelantamiento ordinario?","es":"Visibilidad, espacio y posibilidad de completarlo sin riesgo.","ru":"Обгон возможен лишь при достаточной видимости и безопасном расстоянии.","ruleId":"v3-56","source":"rules"},{"id":"rule-57","lesson":"maniobras","front":"¿Es correcto circular indefinidamente por el carril izquierdo de una autovía libre?","es":"Volver al derecho cuando corresponda.","ru":"На автомагистрали обычно используют правую полосу.","ruleId":"v3-57","source":"rules"},{"id":"rule-58","lesson":"maniobras","front":"Al adelantar con visibilidad reducida por niebla intensa, debes…","es":"No; aplazar el adelantamiento.","ru":"При недостаточной видимости обгон опасен и недопустим.","ruleId":"v3-58","source":"rules"},{"id":"rule-59","lesson":"maniobras","front":"Si una ambulancia se aproxima desde atrás, ¿qué conducta es adecuada?","es":"Facilitar su paso sin poner en peligro a nadie.","ru":"Освободи путь спецтранспорту без создания новой опасности.","ruleId":"v3-59","source":"rules"},{"id":"rule-60","lesson":"maniobras","front":"¿Qué haces tras realizar un cambio de dirección?","es":"Que el indicador de dirección se haya cancelado.","ru":"После поворота отключи сигнал, чтобы не вводить других в заблуждение.","ruleId":"v3-60","source":"rules"},{"id":"rule-61","lesson":"vias","front":"¿Para qué sirve el carril de aceleración?","es":"Ajustar la velocidad e incorporarte cediendo el paso.","ru":"Полоса разгона позволяет безопасно влиться в поток.","ruleId":"v3-61","source":"rules"},{"id":"rule-62","lesson":"vias","front":"¿Para qué sirve el carril de deceleración?","es":"En el carril de deceleración, con seguridad.","ru":"На полосе торможения снижают скорость перед съездом.","ruleId":"v3-62","source":"rules"},{"id":"rule-63","lesson":"vias","front":"¿Puedes detenerte en una autopista para consultar un mensaje?","es":"Continuar hasta un lugar autorizado y seguro.","ru":"На автомагистрали нельзя останавливаться на обочине без необходимости.","ruleId":"v3-63","source":"rules"},{"id":"rule-64","lesson":"vias","front":"En un túnel, ¿qué debe hacerse respecto al alumbrado?","es":"Las luces de cruce conforme a la regulación aplicable.","ru":"В туннеле нужны фары ближнего света.","ruleId":"v3-64","source":"rules"},{"id":"rule-65","lesson":"vias","front":"¿Por qué carril se circula como norma general en autovía?","es":"Por el carril más a la derecha que corresponda.","ru":"На автомагистрали обычно занимают правую полосу.","ruleId":"v3-65","source":"rules"},{"id":"rule-66","lesson":"vias","front":"¿Quién puede utilizar un carril BUS reservado?","es":"Solo los vehículos autorizados por la señalización aplicable.","ru":"Выделенные полосы регулируют знаки и разметка.","ruleId":"v3-66","source":"rules"},{"id":"rule-67","lesson":"vias","front":"Una línea discontinua entre carriles permite cambiar de carril…","es":"Solo si la maniobra está permitida y es segura.","ru":"Прерывистая линия не отменяет обязанность уступать и проверять безопасность.","ruleId":"v3-67","source":"rules"},{"id":"rule-68","lesson":"vias","front":"¿Qué haces cuando un panel indica carril cerrado por obras?","es":"No, debes usar carriles habilitados.","ru":"Красный крест над полосой запрещает движение по ней.","ruleId":"v3-68","source":"rules"},{"id":"rule-69","lesson":"vias","front":"Al aproximarte a un paso a nivel ferroviario con barreras bajadas, debes…","es":"Detenerte antes del paso.","ru":"У железнодорожного переезда нельзя игнорировать закрывающийся шлагбаум.","ruleId":"v3-69","source":"rules"},{"id":"rule-70","lesson":"vias","front":"¿Está permitida la marcha atrás en un túnel para volver a una salida?","es":"Continuar y buscar itinerario seguro.","ru":"В туннеле нельзя сдавать назад из-за ошибки маршрута.","ruleId":"v3-70","source":"rules"},{"id":"rule-71","lesson":"vias","front":"¿Qué debes hacer cuando encuentras un carril reversible?","es":"La señalización específica del carril.","ru":"Реверсивная полоса подчиняется специальной сигнализации.","ruleId":"v3-71","source":"rules"},{"id":"rule-72","lesson":"vias","front":"¿Se permite caminar libremente por el arcén de una autopista?","es":"No; hay que priorizar un lugar seguro y seguir las normas de emergencia.","ru":"Пешеходное движение по автомагистралям опасно и в целом запрещено.","ruleId":"v3-72","source":"rules"},{"id":"rule-73","lesson":"vias","front":"Ante nieve intensa en autopista con circulación dificultada, la reforma de 2026 dispone…","es":"Circular por la derecha y dejar libre el izquierdo para servicios de emergencia y quitanieves.","ru":"При снежных затруднениях сохраняют левую полосу для экстренных служб и снегоуборочной техники.","ruleId":"v3-73","source":"vulnerables2026"},{"id":"rule-74","lesson":"vias","front":"En un carril habilitado en sentido contrario al habitual, debes…","es":"Seguir los dispositivos específicos y extremar la atención.","ru":"Соблюдай специальную схему движения и повышенную осторожность.","ruleId":"v3-74","source":"rules"},{"id":"rule-75","lesson":"vias","front":"¿Debes reducir velocidad antes de alcanzar la entrada de una curva pronunciada?","es":"Antes de entrar en la curva.","ru":"Тормозить и выбирать скорость следует до поворота.","ruleId":"v3-75","source":"rules"},{"id":"rule-76","lesson":"semaforos","front":"¿Qué debes hacer ante luz roja fija de un semáforo?","es":"Detenerte antes de la línea o lugar adecuado.","ru":"Красный свет требует остановки.","ruleId":"v3-76","source":"rules"},{"id":"rule-77","lesson":"semaforos","front":"Ante luz ámbar fija, ¿cuál es la regla general?","es":"Detenerte si puedes hacerlo en condiciones de seguridad.","ru":"На постоянный жёлтый остановись, если это безопасно.","ruleId":"v3-77","source":"rules"},{"id":"rule-78","lesson":"semaforos","front":"¿Qué exige una luz ámbar intermitente?","es":"Extremar precaución y ceder cuando corresponda.","ru":"Мигающий жёлтый требует осторожности и соблюдения приоритета.","ruleId":"v3-78","source":"rules"},{"id":"rule-79","lesson":"semaforos","front":"¿Qué significa una flecha roja en semáforo?","es":"No, en la dirección indicada.","ru":"Красная стрелка запрещает движение в указанном направлении.","ruleId":"v3-79","source":"rules"},{"id":"rule-80","lesson":"semaforos","front":"Ante la orden de alto de un agente, ¿qué haces si tienes verde?","es":"La orden del agente.","ru":"Регулировщик имеет приоритет перед светофором.","ruleId":"v3-80","source":"rules"},{"id":"rule-81","lesson":"semaforos","front":"Una aspa roja sobre un carril indica…","es":"Carril cerrado al tráfico.","ru":"Красный крест закрывает полосу.","ruleId":"v3-81","source":"rules"},{"id":"rule-82","lesson":"semaforos","front":"Una flecha verde de carril sobre un carril indica…","es":"Se permite circular por ese carril en el sentido indicado.","ru":"Зелёная стрелка над полосой разрешает использование.","ruleId":"v3-82","source":"rules"},{"id":"rule-83","lesson":"semaforos","front":"Al cambiar de verde a amarillo, ¿debes acelerar para evitar un rojo?","es":"Frenar y detenerte con seguridad.","ru":"Не ускоряйся на жёлтый; остановись, если безопасно.","ruleId":"v3-83","source":"rules"},{"id":"rule-84","lesson":"semaforos","front":"Si los semáforos están apagados, ¿qué debes aplicar?","es":"Señales presentes y reglas generales aplicables.","ru":"При неработающем светофоре действуют знаки и общие правила.","ruleId":"v3-84","source":"rules"},{"id":"rule-85","lesson":"semaforos","front":"¿Qué significa una luz roja intermitente en un paso a nivel?","es":"Detenerte y no entrar hasta que sea seguro y esté permitido.","ru":"Мигающие красные сигналы на переезде запрещают въезд.","ruleId":"v3-85","source":"rules"},{"id":"rule-86","lesson":"semaforos","front":"Si un paso peatonal tiene semáforo verde para peatones, el conductor…","es":"Respetar su paso y evitar cualquier peligro.","ru":"Не мешай пешеходам на разрешённом переходе.","ruleId":"v3-86","source":"rules"},{"id":"rule-87","lesson":"semaforos","front":"¿Cuál es el papel de un semáforo con silueta de bicicleta?","es":"A los usuarios indicados por ese semáforo.","ru":"Велосипедный светофор регулирует обозначенных участников движения.","ruleId":"v3-87","source":"rules"},{"id":"rule-88","lesson":"semaforos","front":"Si un agente señala con el brazo una orden concreta de detenerse, debes…","es":"Obedecer y detenerte en lugar seguro según su indicación.","ru":"Сигналы регулировщика обязательны.","ruleId":"v3-88","source":"rules"},{"id":"rule-89","lesson":"semaforos","front":"¿Qué importancia tiene la línea de detención?","es":"Antes de franquearla.","ru":"Останавливайся перед стоп-линией.","ruleId":"v3-89","source":"rules"},{"id":"rule-90","lesson":"semaforos","front":"Cuando hay un semáforo exclusivo para bus, ¿debes interpretarlo como señal general para turismos?","es":"No; se aplica a los vehículos a los que está destinado.","ru":"Специальные сигналы относятся к указанным видам транспорта.","ruleId":"v3-90","source":"rules"},{"id":"rule-91","lesson":"estacionamiento","front":"¿En qué se diferencia una parada de un estacionamiento?","es":"Estacionamiento, no parada breve.","ru":"Остановка до двух минут без выхода водителя отличается от стоянки.","ruleId":"v3-91","source":"rules"},{"id":"rule-92","lesson":"estacionamiento","front":"¿Se permite aparcar sobre un paso de peatones?","es":"No.","ru":"На переходе нельзя парковаться.","ruleId":"v3-92","source":"rules"},{"id":"rule-93","lesson":"estacionamiento","front":"¿Es adecuado estacionar en un carril bici reservado?","es":"No, no se debe ocupar el carril reservado.","ru":"Нельзя занимать велосипедную полосу для стоянки.","ruleId":"v3-93","source":"rules"},{"id":"rule-94","lesson":"estacionamiento","front":"Antes de abandonar un coche estacionado, debes…","es":"Que quede correctamente inmovilizado y no pueda desplazarse.","ru":"Убедись, что автомобиль надёжно обездвижен.","ruleId":"v3-94","source":"rules"},{"id":"rule-95","lesson":"estacionamiento","front":"¿Puedes bloquear la entrada y salida de un garaje autorizado?","es":"No, si obstaculizas el acceso autorizado.","ru":"Нельзя блокировать разрешённый въезд в гараж.","ruleId":"v3-95","source":"rules"},{"id":"rule-96","lesson":"estacionamiento","front":"¿Puedes detenerte en un carril reservado BUS sin motivo habilitante?","es":"No, respeta la reserva y señalización.","ru":"Нельзя использовать автобусную полосу как место для остановки.","ruleId":"v3-96","source":"rules"},{"id":"rule-97","lesson":"estacionamiento","front":"¿Qué debes comprobar antes de abrir una puerta junto a una ciclovía?","es":"Solo cuando no ponga en peligro a nadie.","ru":"Открывай двери только после проверки безопасности.","ruleId":"v3-97","source":"rules"},{"id":"rule-98","lesson":"estacionamiento","front":"En una zona de estacionamiento regulado municipal, debes…","es":"Las condiciones y limitaciones específicas de la zona.","ru":"Учитывай правила и оплату парковочной зоны.","ruleId":"v3-98","source":"rules"},{"id":"rule-99","lesson":"estacionamiento","front":"¿Puede estacionarse en segunda fila como regla general?","es":"Buscar un lugar permitido.","ru":"Стоянка вторым рядом, мешающая движению, не допускается.","ruleId":"v3-99","source":"rules"},{"id":"rule-100","lesson":"estacionamiento","front":"Una parada voluntaria por menos de dos minutos exige que el conductor…","es":"No, al abandonar el vehículo deja de ser una parada reglamentaria.","ru":"Для «parada» водитель остаётся в автомобиле и время не превышает двух минут.","ruleId":"v3-100","source":"rules"},{"id":"rule-101","lesson":"estacionamiento","front":"¿Dónde deben realizarse las operaciones de carga si una señal restringe el espacio?","es":"No, salvo autorización o condiciones indicadas.","ru":"Зона погрузки/разгрузки подчиняется специальным правилам.","ruleId":"v3-101","source":"rules"},{"id":"rule-102","lesson":"estacionamiento","front":"¿Qué haces si un lugar de aparcamiento tapa una señal esencial?","es":"No, debes evitar estacionar donde obstaculices la visibilidad de señales.","ru":"Не блокируй видимость дорожных знаков.","ruleId":"v3-102","source":"rules"},{"id":"rule-103","lesson":"estacionamiento","front":"En una curva de visibilidad reducida, ¿puedes estacionar libremente?","es":"No estacionar donde se genere peligro o esté prohibido.","ru":"Стоянка в опасной зоне без видимости запрещена.","ruleId":"v3-103","source":"rules"},{"id":"rule-104","lesson":"estacionamiento","front":"Al estacionar en pendiente, ¿qué debes prevenir?","es":"Impedir que se mueva accidentalmente.","ru":"На уклоне предотврати самопроизвольное движение.","ruleId":"v3-104","source":"rules"},{"id":"rule-105","lesson":"estacionamiento","front":"¿Puede un vehículo ocupar un espacio reservado para personas con movilidad reducida sin habilitación?","es":"No.","ru":"Места для людей с ограниченной мобильностью защищены.","ruleId":"v3-105","source":"rules"},{"id":"rule-106","lesson":"seguridad","front":"¿Para qué sirve principalmente el cinturón de seguridad?","es":"Reduce el riesgo de lesiones graves al sujetar al ocupante.","ru":"Ремень удерживает пассажира и снижает тяжесть травм.","ruleId":"v3-106","source":"rules"},{"id":"rule-107","lesson":"seguridad","front":"¿El airbag sustituye al cinturón?","es":"No, trabajan conjuntamente.","ru":"Подушка дополняет ремень, но не заменяет его.","ruleId":"v3-107","source":"rules"},{"id":"rule-108","lesson":"seguridad","front":"¿Qué debes verificar sobre el reposacabezas antes de conducir?","es":"Reducir posibles lesiones cervicales.","ru":"Подголовник помогает снизить травмы шеи.","ruleId":"v3-108","source":"rules"},{"id":"rule-109","lesson":"seguridad","front":"¿Qué precaución es esencial al transportar niños pequeños?","es":"Un sistema homologado y adecuado según normativa.","ru":"Дети должны использовать подходящее удерживающее устройство.","ruleId":"v3-109","source":"rules"},{"id":"rule-110","lesson":"seguridad","front":"En una carretera mojada, ¿qué cambia respecto a una seca?","es":"Menor adherencia y posibilidad de aquaplaning.","ru":"На мокрой дороге сцепление ухудшается и возможен аквапланинг.","ruleId":"v3-110","source":"rules"},{"id":"rule-111","lesson":"seguridad","front":"¿Qué haces si aparece somnolencia intensa al volante?","es":"Detenerte en lugar seguro y descansar.","ru":"При сонливости остановись и отдохни.","ruleId":"v3-111","source":"rules"},{"id":"rule-112","lesson":"seguridad","front":"¿Qué sistema ayuda a evitar el bloqueo de ruedas al frenar con fuerza?","es":"Ayuda a evitar el bloqueo de las ruedas.","ru":"ABS предотвращает блокировку колёс при экстренном торможении.","ruleId":"v3-112","source":"rules"},{"id":"rule-113","lesson":"seguridad","front":"¿De qué depende la distancia de seguridad necesaria?","es":"Una que permita detenerte sin colisión, ampliada por condiciones adversas.","ru":"Безопасная дистанция зависит от скорости, сцепления и обзорности.","ruleId":"v3-113","source":"rules"},{"id":"rule-114","lesson":"seguridad","front":"¿Qué debes hacer si el parabrisas se empaña mientras circulas?","es":"Restablecer la visibilidad con climatización o desempañado y actuar con prudencia.","ru":"При запотевшем стекле восстанови обзор.","ruleId":"v3-114","source":"rules"},{"id":"rule-115","lesson":"seguridad","front":"¿Es buena idea sujetar un móvil para usar GPS en marcha?","es":"No; evita su manipulación y distracción.","ru":"Не держи телефон за рулём: это опасное отвлечение.","ruleId":"v3-115","source":"rules"},{"id":"rule-116","lesson":"seguridad","front":"¿Qué debe hacer el conductor ante un peatón distraído cerca de la calzada?","es":"Anticipar posible invasión y reducir riesgo.","ru":"Предвидь непредсказуемые действия пешехода.","ruleId":"v3-116","source":"rules"},{"id":"rule-117","lesson":"seguridad","front":"¿Qué papel tienen los neumáticos en una frenada?","es":"Disminuyen la adherencia y aumentan el riesgo.","ru":"Изношенные шины ухудшают сцепление и торможение.","ruleId":"v3-117","source":"rules"},{"id":"rule-118","lesson":"seguridad","front":"En un trayecto corto, ¿debe abrocharse el cinturón?","es":"No, debes utilizarlo según la regulación aplicable.","ru":"Ремень нужен и на коротких поездках.","ruleId":"v3-118","source":"rules"},{"id":"rule-119","lesson":"seguridad","front":"¿Qué haces ante un perro suelto al borde de una carretera?","es":"Reducir velocidad y estar preparado para reaccionar sin maniobras peligrosas.","ru":"Животное может внезапно выбежать на дорогу.","ruleId":"v3-119","source":"rules"},{"id":"rule-120","lesson":"seguridad","front":"Al circular de noche, ¿qué factor aumenta la necesidad de precaución?","es":"Adaptar velocidad a distancia de visibilidad iluminada.","ru":"Ночью скорость должна соответствовать видимой зоне остановки.","ruleId":"v3-120","source":"rules"},{"id":"rule-121","lesson":"alcohol","front":"¿Cuál es la mejor decisión si has consumido alcohol y dudas de tu estado?","es":"No conducir y buscar alternativa segura.","ru":"После алкоголя безопаснее не садиться за руль.","ruleId":"v3-121","source":"rules"},{"id":"rule-122","lesson":"alcohol","front":"¿Puede el café reducir la alcoholemia de forma inmediata?","es":"No.","ru":"Кофе не устраняет алкоголь из крови.","ruleId":"v3-122","source":"rules"},{"id":"rule-123","lesson":"alcohol","front":"¿Tomar una ducha fría elimina la intoxicación alcohólica?","es":"No.","ru":"Холодный душ не ускоряет удаление алкоголя.","ruleId":"v3-123","source":"rules"},{"id":"rule-124","lesson":"alcohol","front":"¿Qué efecto puede tener un medicamento con advertencia de somnolencia?","es":"Puede reducir atención y capacidad de reacción.","ru":"Лекарства могут вызвать сонливость и замедлить реакцию.","ruleId":"v3-124","source":"rules"},{"id":"rule-125","lesson":"alcohol","front":"¿Por qué es peligrosa la fatiga en viajes largos?","es":"Disminuye la atención y aumenta el tiempo de reacción.","ru":"Усталость ухудшает внимание и время реакции.","ruleId":"v3-125","source":"rules"},{"id":"rule-126","lesson":"alcohol","front":"¿Es recomendable conducir tras consumir drogas que afectan al sistema nervioso?","es":"No conducir.","ru":"Наркотики и психоактивные вещества несовместимы с безопасным вождением.","ruleId":"v3-126","source":"rules"},{"id":"rule-127","lesson":"alcohol","front":"Si en un control te requieren someterte a pruebas legales de alcohol, debes…","es":"Cumplir la obligación legal de someterte a ella.","ru":"Отказ от законного теста на алкоголь может влечь серьёзные последствия.","ruleId":"v3-127","source":"rules"},{"id":"rule-128","lesson":"alcohol","front":"¿Qué relación tiene el alcohol con la percepción de riesgos?","es":"El alcohol altera juicio y percepción del peligro.","ru":"Алкоголь ухудшает оценку опасности.","ruleId":"v3-128","source":"rules"},{"id":"rule-129","lesson":"alcohol","front":"¿Puede el alcohol alterar la coordinación de movimientos?","es":"Disminuye coordinación y control.","ru":"Алкоголь нарушает координацию.","ruleId":"v3-129","source":"rules"},{"id":"rule-130","lesson":"alcohol","front":"¿La cantidad de alcohol tolerada legalmente es una recomendación de consumo?","es":"No; la opción segura es cero alcohol.","ru":"Предел в законе не означает, что пить до предела безопасно.","ruleId":"v3-130","source":"rules"},{"id":"rule-131","lesson":"alcohol","front":"¿Puede el consumo conjunto de alcohol y medicamentos agravar sus efectos?","es":"Pueden potenciarse los efectos peligrosos.","ru":"Алкоголь и лекарства могут усилить опасные эффекты друг друга.","ruleId":"v3-131","source":"rules"},{"id":"rule-132","lesson":"alcohol","front":"¿Qué haces si notas microsueños mientras conduces?","es":"Parar en un lugar seguro y descansar de verdad.","ru":"Микросон — критический сигнал прекратить вождение и отдохнуть.","ruleId":"v3-132","source":"rules"},{"id":"rule-133","lesson":"alcohol","front":"¿Es seguro usar el móvil en un semáforo rojo para escribir mensajes?","es":"La manipulación del teléfono durante la conducción.","ru":"Манипуляции с телефоном отвлекают, в том числе при краткой остановке.","ruleId":"v3-133","source":"rules"},{"id":"rule-134","lesson":"alcohol","front":"¿Por qué se debe planificar descanso en desplazamientos largos?","es":"Organizar pausas periódicas y descanso suficiente.","ru":"Перерывы и достаточный сон снижают риск усталости.","ruleId":"v3-134","source":"rules"},{"id":"rule-135","lesson":"alcohol","front":"¿Qué impacto tiene una distracción visual de dos segundos a velocidad de carretera?","es":"Recorres una distancia significativa sin observar el entorno.","ru":"Даже две секунды отвлечения означают десятки метров без контроля дороги.","ruleId":"v3-135","source":"rules"},{"id":"rule-136","lesson":"vehiculo","front":"¿Qué debe comprobarse periódicamente en los neumáticos?","es":"Presión, estado y profundidad del dibujo.","ru":"Следи за давлением, состоянием и протектором шин.","ruleId":"v3-136","source":"rules"},{"id":"rule-137","lesson":"vehiculo","front":"¿Cuál es la profundidad mínima legal general del dibujo de neumáticos de turismo?","es":"No, el mínimo es 1,6 mm.","ru":"Для легковых машин минимальная глубина протектора обычно 1,6 мм.","ruleId":"v3-137","source":"rules"},{"id":"rule-138","lesson":"vehiculo","front":"¿Qué debes comprobar si el testigo rojo de aceite se ilumina en marcha?","es":"Detenerte de forma segura y atender inmediatamente el problema.","ru":"Красная лампа давления масла требует срочной безопасной остановки.","ruleId":"v3-138","source":"rules"},{"id":"rule-139","lesson":"vehiculo","front":"¿Para qué sirven los retrovisores?","es":"Los espejos, complementados con la observación directa.","ru":"Зеркала помогают контролировать обстановку позади, но слепые зоны проверяют отдельно.","ruleId":"v3-139","source":"rules"},{"id":"rule-140","lesson":"vehiculo","front":"¿Qué significa ABS en la seguridad del vehículo?","es":"Ayuda a evitar el bloqueo de ruedas y mantener capacidad de dirección.","ru":"ABS помогает управлять машиной при интенсивном торможении.","ruleId":"v3-140","source":"rules"},{"id":"rule-141","lesson":"vehiculo","front":"¿Para qué sirve el líquido de frenos?","es":"El sistema hidráulico de frenos.","ru":"Тормозная жидкость необходима гидравлическому приводу тормозов.","ruleId":"v3-141","source":"rules"},{"id":"rule-142","lesson":"vehiculo","front":"¿Qué debes hacer antes de arrancar un vehículo desconocido?","es":"Asiento, espejos, cinturón y mandos esenciales.","ru":"Перед поездкой настрой сиденье, зеркала, ремень и органы управления.","ruleId":"v3-142","source":"rules"},{"id":"rule-143","lesson":"vehiculo","front":"¿Para qué sirve el refrigerante del motor?","es":"El sistema de refrigeración.","ru":"Охлаждающая система предотвращает перегрев двигателя.","ruleId":"v3-143","source":"rules"},{"id":"rule-144","lesson":"vehiculo","front":"¿Qué puede indicar una vibración anormal durante el frenado?","es":"Comprobar el sistema de frenos en un taller.","ru":"Ненормальная вибрация при торможении требует проверки.","ruleId":"v3-144","source":"rules"},{"id":"rule-145","lesson":"vehiculo","front":"¿Cuál es una función del alumbrado de cruce?","es":"Visibilidad propia y ser visto sin deslumbrar en condiciones normales.","ru":"Ближний свет помогает видеть дорогу и быть заметным, не ослепляя других.","ruleId":"v3-145","source":"rules"},{"id":"rule-146","lesson":"vehiculo","front":"¿Qué debes hacer si un limpiaparabrisas deja de despejar el cristal?","es":"Restablecer la visibilidad y revisar el estado de las escobillas.","ru":"Необходимо восстановить обзор и заменить изношенные щётки.","ruleId":"v3-146","source":"rules"},{"id":"rule-147","lesson":"vehiculo","front":"¿Para qué sirve el freno de estacionamiento?","es":"El freno de estacionamiento.","ru":"Стояночный тормоз удерживает автомобиль.","ruleId":"v3-147","source":"rules"},{"id":"rule-148","lesson":"vehiculo","front":"¿Qué función tienen los indicadores de dirección?","es":"Los intermitentes.","ru":"Поворотники информируют о намерении сменить направление.","ruleId":"v3-148","source":"rules"},{"id":"rule-149","lesson":"vehiculo","front":"¿Qué significa una luz de batería encendida mientras circulas?","es":"Posible fallo del sistema eléctrico de carga.","ru":"Лампа аккумулятора может указывать на неисправность зарядки.","ruleId":"v3-149","source":"rules"},{"id":"rule-150","lesson":"vehiculo","front":"¿Por qué no se deben descuidar los amortiguadores?","es":"La suspensión y amortiguadores.","ru":"Амортизаторы влияют на сцепление и устойчивость.","ruleId":"v3-150","source":"rules"},{"id":"rule-151","lesson":"documentos","front":"¿Qué permiso autoriza a conducir turismos ordinarios según sus límites?","es":"Permiso B.","ru":"Для обычного легкового автомобиля нужен Permiso B.","ruleId":"v3-151","source":"conductors"},{"id":"rule-152","lesson":"documentos","front":"¿Qué documento identifica legalmente la aptitud del conductor para esa categoría?","es":"El permiso de conducción vigente aplicable.","ru":"Водительское удостоверение подтверждает право управлять данной категорией.","ruleId":"v3-152","source":"conductors"},{"id":"rule-153","lesson":"documentos","front":"¿Para qué sirve la ITV periódica?","es":"Condiciones técnicas y de seguridad reglamentarias.","ru":"ITV проверяет техническое состояние и соответствие нормам.","ruleId":"v3-153","source":"rules"},{"id":"rule-154","lesson":"documentos","front":"¿Qué obliga el seguro de responsabilidad civil?","es":"Cubrir la responsabilidad civil mínima exigida.","ru":"Обязательное страхование покрывает предусмотренную гражданскую ответственность.","ruleId":"v3-154","source":"rules"},{"id":"rule-155","lesson":"documentos","front":"¿Qué caracteriza el permiso de circulación del vehículo?","es":"La autorización administrativa para que ese vehículo circule.","ru":"Свидетельство регистрации автомобиля относится к допуску машины к движению.","ruleId":"v3-155","source":"rules"},{"id":"rule-156","lesson":"documentos","front":"¿El permiso B común permite conducir sin límites cualquier camión?","es":"No, el B tiene límites de vehículos y masas.","ru":"Категория B не даёт права управлять любым грузовиком.","ruleId":"v3-156","source":"conductors"},{"id":"rule-157","lesson":"documentos","front":"¿Debes comprobar cuándo caduca la ITV?","es":"La vigencia de la inspección técnica aplicable.","ru":"Следи за сроком действительности ITV.","ruleId":"v3-157","source":"rules"},{"id":"rule-158","lesson":"documentos","front":"¿Qué sucede si conduces pese a una pérdida de vigencia del permiso?","es":"No, necesitas la autorización válida que corresponda.","ru":"Без действительного права управления водить нельзя.","ruleId":"v3-158","source":"conductors"},{"id":"rule-159","lesson":"documentos","front":"¿Un conductor novel debe cumplir requisitos de documentación y distintivos?","es":"Los requisitos aplicables, incluido distintivo V-13 cuando corresponda.","ru":"Начинающий водитель соблюдает специальные требования, включая знак L по правилам.","ruleId":"v3-159","source":"rules"},{"id":"rule-160","lesson":"documentos","front":"¿Pueden existir limitaciones de circulación por ZBE municipal?","es":"Normativa local aplicable y restricciones vigentes.","ru":"В низкоэмиссионной зоне учитывай местные ограничения.","ruleId":"v3-160","source":"rules"},{"id":"rule-161","lesson":"documentos","front":"¿Qué implica perder puntos del permiso?","es":"Tu saldo del permiso por puntos.","ru":"За нарушения могут списываться баллы водительского удостоверения.","ruleId":"v3-161","source":"conductors"},{"id":"rule-162","lesson":"documentos","front":"¿Puedes compartir tu permiso de conducir con otra persona para que conduzca por ti?","es":"No, el permiso es personal.","ru":"Права именные и не могут передаваться другому водителю.","ruleId":"v3-162","source":"conductors"},{"id":"rule-163","lesson":"documentos","front":"¿Qué información pueden proporcionar los agentes en un control de tráfico?","es":"Cooperar y presentar la documentación legalmente exigible.","ru":"При законной проверке предоставляют требуемые документы.","ruleId":"v3-163","source":"rules"},{"id":"rule-164","lesson":"documentos","front":"¿Para qué sirve la etiqueta ambiental de la DGT?","es":"El distintivo ambiental asignado al vehículo.","ru":"Экологическая маркировка связана с классификацией выбросов.","ruleId":"v3-164","source":"rules"},{"id":"rule-165","lesson":"documentos","front":"¿La vigencia del permiso de conducir puede requerir renovación?","es":"Renovarlo según el procedimiento y requisitos aplicables.","ru":"Водительское удостоверение имеет срок действия и требует продления.","ruleId":"v3-165","source":"conductors"},{"id":"rule-166","lesson":"emergencias","front":"¿Qué significa PAS al asistir en un siniestro?","es":"Proteger, avisar y socorrer.","ru":"Порядок помощи: защитить, сообщить, оказать помощь.","ruleId":"v3-166","source":"rules"},{"id":"rule-167","lesson":"emergencias","front":"¿A qué número llamas para emergencias en España?","es":"112.","ru":"Экстренный номер в Испании — 112.","ruleId":"v3-167","source":"rules"},{"id":"rule-168","lesson":"emergencias","front":"¿Debes mover de inmediato a todo herido tras un siniestro?","es":"Evitar moverla sin necesidad salvo peligro inminente y seguir instrucciones sanitarias.","ru":"Пострадавшего обычно не перемещают без крайней необходимости.","ruleId":"v3-168","source":"rules"},{"id":"rule-169","lesson":"emergencias","front":"¿Qué debes priorizar al detenerte junto a un accidente?","es":"Proteger la escena y evitar nuevos riesgos.","ru":"Сначала обеспечь безопасность места происшествия.","ruleId":"v3-169","source":"rules"},{"id":"rule-170","lesson":"emergencias","front":"Desde 2026, ¿qué baliza debe llevar un turismo español para señalizar inmovilización?","es":"La V-16 conectada y homologada.","ru":"С 2026 года требуется подключённый сертифицированный маяк V-16.","ruleId":"v3-170","source":"v16"},{"id":"rule-171","lesson":"emergencias","front":"¿Son suficientes los triángulos tradicionales como único sistema de preseñalización para un turismo en España en 2026?","es":"No, se exige la V-16 conectada homologada.","ru":"В 2026 году треугольники уже не заменяют обязательный маяк V-16.","ruleId":"v3-171","source":"v16"},{"id":"rule-172","lesson":"emergencias","front":"¿Dónde se coloca normalmente la baliza V-16 conectada para advertir?","es":"En la parte más alta posible del vehículo, según instrucciones y sin exponerse.","ru":"Маяк V-16 размещают высоко на машине, не подвергая себя риску.","ruleId":"v3-172","source":"v16"},{"id":"rule-173","lesson":"emergencias","front":"¿Qué debes hacer si no es seguro abandonar el vehículo averiado en autopista?","es":"No exponerte y seguir las recomendaciones de protección y emergencia.","ru":"Нельзя выходить на опасную проезжую часть ради установки предупреждений.","ruleId":"v3-173","source":"v16"},{"id":"rule-174","lesson":"emergencias","front":"Si encuentras un objeto caído en autopista, ¿qué haces?","es":"Reducir el riesgo, evitar maniobras bruscas y comunicar la incidencia.","ru":"При препятствии избеги резких манёвров, предупреди службы.","ruleId":"v3-174","source":"rules"},{"id":"rule-175","lesson":"emergencias","front":"¿Qué información conviene comunicar al llamar al 112?","es":"Localización, tipo de incidente y número aproximado de afectados.","ru":"Службе 112 сообщают место и характер происшествия.","ruleId":"v3-175","source":"rules"},{"id":"rule-176","lesson":"emergencias","front":"¿Qué debes hacer si detectas fuego en tu coche mientras circulas?","es":"Detenerte en lugar seguro, alejarte si procede y alertar servicios de emergencia.","ru":"При дыме и пожаре нужна безопасная остановка и вызов помощи.","ruleId":"v3-176","source":"rules"},{"id":"rule-177","lesson":"emergencias","front":"Si la carretera tiene vehículos accidentados y agentes auxiliando, la reforma de 2026 obliga al rebasarlos a…","es":"Dejar al menos 1,5 m y reducir al menos 20 km/h respecto al límite.","ru":"По новому правилу 2026 года нужны 1,5 м сбоку и скорость минимум на 20 км/ч ниже лимита.","ruleId":"v3-177","source":"vulnerables2026"},{"id":"rule-178","lesson":"emergencias","front":"¿Qué haces si observas a alguien caminando por el arcén tras una avería?","es":"Extremar precaución, reducir velocidad y mantener distancia segura.","ru":"Рядом с аварией особенно защищай людей на обочине.","ruleId":"v3-178","source":"rules"},{"id":"rule-179","lesson":"emergencias","front":"¿Qué significa un carril de emergencia en retenciones según la reforma 2026?","es":"Apartándose para dejar libre un corredor central.","ru":"При заторе машины освобождают центральный коридор для экстренных служб.","ruleId":"v3-179","source":"vulnerables2026"},{"id":"rule-180","lesson":"emergencias","front":"¿Qué haces si hay riesgo eléctrico por cables caídos tras un accidente?","es":"Mantener distancia, evitar contacto y alertar a emergencias.","ru":"При обрыве проводов держись подальше и сообщи экстренным службам.","ruleId":"v3-180","source":"rules"},{"id":"rule-181","lesson":"senales","front":"¿Qué significa la señal de ceda el paso ante una glorieta?","es":"Ceder a quienes circulan por la glorieta.","ru":"Въезжающий на круг уступает тем, кто уже движется по кругу.","ruleId":"v3-181","source":"rules"},{"id":"rule-182","lesson":"senales","front":"¿Puede una señal luminosa de carril prohibir utilizarlo aunque la marca vial sea discontinua?","es":"La prohibición luminosa del carril.","ru":"Красный крест над полосой действует независимо от прерывистой разметки.","ruleId":"v3-182","source":"rules"},{"id":"rule-183","lesson":"senales","front":"¿Qué función general tiene una señal de obligación azul?","es":"Una obligación de circulación o equipamiento indicado.","ru":"Синие круглые знаки обычно устанавливают предписания.","ruleId":"v3-183","source":"signs"},{"id":"rule-184","lesson":"senales","front":"¿Qué debes hacer si una señal indica fin de una prohibición anterior?","es":"Deja de aplicarse esa limitación específica, permaneciendo las normas generales.","ru":"Конец ограничения отменяет конкретный режим, но не общие нормы.","ruleId":"v3-184","source":"signs"},{"id":"rule-185","lesson":"prioridad","front":"¿Qué debes hacer si una ambulancia en servicio urgente necesita pasar por una retención?","es":"Orillarte de forma segura y colaborar en dejar el espacio central libre.","ru":"В заторе освобождают центральный проход для экстренных служб.","ruleId":"v3-185","source":"vulnerables2026"},{"id":"rule-186","lesson":"prioridad","front":"En una vía de tráfico calmado con peatones cerca, ¿cuál es el principio esencial?","es":"Evitar el riesgo para los usuarios más vulnerables.","ru":"На улицах совместного пользования уязвимых участников нужно особенно защищать.","ruleId":"v3-186","source":"vulnerables2026"},{"id":"rule-187","lesson":"prioridad","front":"Al girar a la derecha con un ciclista próximo, ¿qué debes observar?","es":"Cortar su trayectoria y ponerlo en peligro.","ru":"Перед правым поворотом не пересекай траекторию велосипедиста.","ruleId":"v3-187","source":"vulnerables2026"},{"id":"rule-188","lesson":"prioridad","front":"Cuando un vehículo prioritario emite señales especiales, la regla general es…","es":"Facilitar su paso tomando precauciones.","ru":"Службы экстренного реагирования надо безопасно пропускать.","ruleId":"v3-188","source":"rules"},{"id":"rule-189","lesson":"velocidad","front":"A 30 km/h en una calle residencial, ¿es seguro seguir a 30 si hay niños jugando junto a la vía?","es":"Una menor si el riesgo y la visibilidad lo exigen.","ru":"При риске для детей снижай скорость даже ниже установленного максимума.","ruleId":"v3-189","source":"rules"},{"id":"rule-190","lesson":"velocidad","front":"En una carretera de 90, una señal temporal de 60 obliga a…","es":"60 km/h mientras la señal sea aplicable.","ru":"Временный лимит 60 действует поверх обычного 90.","ruleId":"v3-190","source":"rules"},{"id":"rule-191","lesson":"velocidad","front":"¿Qué ocurre con la distancia recorrida durante un segundo de reacción al aumentar velocidad?","es":"A 100 recorres aproximadamente el doble en ese segundo.","ru":"За одинаковую секунду на большей скорости проезжаешь больше метров.","ruleId":"v3-191","source":"rules"},{"id":"rule-192","lesson":"velocidad","front":"¿Qué caracteriza al aquaplaning?","es":"Aquaplaning.","ru":"Аквапланирование — потеря контакта шины с дорогой на слое воды.","ruleId":"v3-192","source":"rules"},{"id":"rule-193","lesson":"maniobras","front":"Desde octubre de 2026, ¿qué distancia mínima guardas detrás de una bicicleta en el mismo carril?","es":"Al menos cinco metros.","ru":"В одном ряду за велосипедистом держи не менее пяти метров.","ruleId":"v3-193","source":"vulnerables2026"},{"id":"rule-194","lesson":"maniobras","front":"¿Puede omitirse la separación de 1,5 m al adelantar a un ciclista porque llevas un coche pequeño?","es":"Al menos 1,5 m en los casos regulados.","ru":"Размер автомобиля не отменяет 1,5 м бокового интервала.","ruleId":"v3-194","source":"vulnerables2026"},{"id":"rule-195","lesson":"maniobras","front":"Para rebasar un vehículo detenido por accidente, ¿se aplica una precaución especial desde octubre 2026?","es":"Al menos 1,5 m lateral y reducir al menos 20 km/h respecto al límite.","ru":"При объезде аварии защищай работников: 1,5 м и скорость минимум на 20 км/ч ниже лимита.","ruleId":"v3-195","source":"vulnerables2026"},{"id":"rule-196","lesson":"maniobras","front":"Al adelantar ciclistas en calzada con más de un carril por sentido, debes…","es":"Cambiar totalmente al carril contiguo, guardando seguridad.","ru":"В многополосной дороге при обгоне велосипедиста требуется полная смена полосы.","ruleId":"v3-196","source":"vulnerables2026"},{"id":"rule-197","lesson":"vias","front":"En un atasco de autopista con vehículos casi detenidos, ¿cómo se facilita el paso de emergencias?","es":"En un corredor central libre, colaborando los conductores.","ru":"С 2026 года при заторах освобождают центральный коридор.","ruleId":"v3-197","source":"vulnerables2026"},{"id":"rule-198","lesson":"vias","front":"¿Cuál es el comportamiento previsto en autopista cuando la nieve dificulta la circulación?","es":"Mantenerse en el derecho y reservar el izquierdo para emergencia y quitanieves.","ru":"При сильном снегопаде держись справа, освободив левую полосу.","ruleId":"v3-198","source":"vulnerables2026"},{"id":"rule-199","lesson":"vias","front":"¿Son siempre válidas para turismos las indicaciones de un carril VAO?","es":"Solo quienes cumplan los requisitos y excepciones indicados.","ru":"Полосы VAO доступны на установленных условиях.","ruleId":"v3-199","source":"rules"},{"id":"rule-200","lesson":"semaforos","front":"¿Qué exige un ámbar intermitente si en un cruce hay un peatón?","es":"Extremar precaución y respetar su prioridad.","ru":"Мигающий жёлтый не отменяет приоритет пешеходов.","ruleId":"v3-200","source":"rules"},{"id":"rule-201","lesson":"semaforos","front":"¿Qué función tiene una señal luminosa de velocidad variable?","es":"El indicado temporalmente por el panel.","ru":"Переменные электронные ограничения обязательны.","ruleId":"v3-201","source":"rules"},{"id":"rule-202","lesson":"estacionamiento","front":"¿Puede estacionarse sobre la acera con un turismo por ausencia de señal?","es":"No, salvo casos expresamente habilitados legalmente.","ru":"Тротуар не является обычной парковкой автомобиля.","ruleId":"v3-202","source":"rules"},{"id":"rule-203","lesson":"estacionamiento","front":"¿Está permitido estacionar en una parada de autobús señalizada?","es":"No, respeta el espacio reservado.","ru":"Автобусные остановки нельзя занимать вопреки резервированию.","ruleId":"v3-203","source":"rules"},{"id":"rule-204","lesson":"seguridad","front":"¿Qué efecto puede tener la conducción nocturna sobre el tiempo disponible para detectar obstáculos?","es":"Menor alcance de visión y necesidad de adaptar velocidad.","ru":"Ночью видимость ограничена, скорость должна это учитывать.","ruleId":"v3-204","source":"rules"},{"id":"rule-205","lesson":"seguridad","front":"En presencia de usuarios vulnerables, ¿qué conducta global exige la reforma de 2026?","es":"Prevenir riesgos y guardar separación suficiente, cumpliendo reglas específicas.","ru":"Новые правила 2026 усиливают защиту уязвимых участников.","ruleId":"v3-205","source":"vulnerables2026"},{"id":"rule-206","lesson":"seguridad","front":"¿Por qué hay que anticipar el cambio brusco de trayectoria de un ciclista?","es":"Que el ciclista puede desviarse para evitar el obstáculo.","ru":"Велосипедист может объехать яму, поэтому оставляй пространство.","ruleId":"v3-206","source":"rules"},{"id":"rule-207","lesson":"alcohol","front":"¿Es posible dar positivo sin percibir embriaguez?","es":"No, la percepción subjetiva no garantiza aptitud ni tasa legal.","ru":"Самочувствие не определяет безопасную или законную концентрацию алкоголя.","ruleId":"v3-207","source":"rules"},{"id":"rule-208","lesson":"alcohol","front":"¿Qué riesgo generan determinadas drogas para la atención?","es":"Mayor peligro por alteración de juicio, reacción y atención.","ru":"Психоактивные вещества искажают время, внимание и реакции.","ruleId":"v3-208","source":"rules"},{"id":"rule-209","lesson":"vehiculo","front":"¿Por qué debes comprobar el alumbrado antes de un viaje nocturno?","es":"Solucionar la avería antes de circular en condiciones que exigen ese alumbrado.","ru":"Неисправный свет снижает видимость и нарушает требования.","ruleId":"v3-209","source":"rules"},{"id":"rule-210","lesson":"vehiculo","front":"¿Cuál es la función de los sistemas ADAS de ayuda al conductor?","es":"No, las ayudas no sustituyen atención y control del conductor.","ru":"Системы помощи не заменяют внимание водителя.","ruleId":"v3-210","source":"rules"},{"id":"rule-211","lesson":"documentos","front":"¿Pueden existir reglas de circulación adicionales en zonas urbanas de bajas emisiones?","es":"La regulación vigente de esa zona concreta.","ru":"В ZBE действуют конкретные местные экологические правила.","ruleId":"v3-211","source":"rules"},{"id":"rule-212","lesson":"documentos","front":"¿Se actualizó en 2026 el marco estatal de protección de usuarios vulnerables?","es":"El Real Decreto 518/2026.","ru":"RD 518/2026 усилил защиту уязвимых участников движения.","ruleId":"v3-212","source":"vulnerables2026"},{"id":"rule-213","lesson":"emergencias","front":"¿Por qué no debes caminar por la calzada para colocar triángulos tras avería en autopista?","es":"Evitar exponerte al tráfico y utilizar la baliza legal cuando pueda hacerse con seguridad.","ru":"Маяк V-16 разработан, чтобы не выходить на опасную дорогу ради треугольников.","ruleId":"v3-213","source":"v16"},{"id":"rule-214","lesson":"emergencias","front":"Una baliza V-16 antigua no conectada, ¿sustituye a la V-16 exigida en España desde enero 2026?","es":"No, debe ser conectada y cumplir la homologación requerida.","ru":"В 2026 требуется сертифицированная подключённая V-16.","ruleId":"v3-214","source":"v16"},{"id":"rule-215","lesson":"emergencias","front":"¿Debes asegurar la propia protección antes de auxiliar a otros en accidente?","es":"No convertirte en una víctima más: protege y avisa.","ru":"Прежде чем помогать, исключи опасность для себя и других.","ruleId":"v3-215","source":"rules"},{"id":"rule-216","lesson":"emergencias","front":"¿El teléfono 112 sirve para emergencias de tráfico en toda España?","es":"112.","ru":"112 — общеевропейский экстренный номер, действующий в Испании.","ruleId":"v3-216","source":"rules"}];
EXTRA_FLASHCARDS.push(...V3_REVIEW_CARDS);
